const items = $input.all();
const allowedPurpose = new Set(['Хочу купити','Хочу орендувати','Хочу продати','Хочу здати в оренду']);
const allowedType = new Set(['Квартира','Будинок','Комерційне приміщення','Земля']);
const results = [];
for (let index = 0; index < items.length; index++) {
  const data = items[index].json.body ?? items[index].json;
  const sourceTimestamp = String(data['Отметка времени'] ?? data['Позначка часу'] ?? data['Відмітка часу'] ?? data.Timestamp ?? data.timestamp ?? '').trim();
  const stableId = String(data.source_row_id ?? `19yHm6hi7G2b8s3y8pFVSoCn8m3HiWJDlFr_CdXMnoUg:567687119:${encodeURIComponent(sourceTimestamp || `item-${index}`)}`);
  const reject = (code, explanation) => ({ json: { validation_status: 'REJECTED', source_row_id: stableId, validation_error_code: code, validation_error: explanation, processed_at: new Date().toISOString() } });
  const value = (name, alt) => String(data[name] ?? (alt ? data[alt] : '') ?? '').trim();
  const full_name = value('ПІБ', 'full_name');
  if (!full_name) { results.push(reject('MISSING_FULL_NAME', 'Не вказано ПІБ')); continue; }
  const phone = value('Контактний телефон', 'phone');
  if (!phone) { results.push(reject('MISSING_PHONE', 'Не вказано контактний телефон')); continue; }
  if (!/^\+?[0-9 ()-]{10,20}$/.test(phone)) { results.push(reject('INVALID_PHONE', 'Некоректний формат телефону')); continue; }
  const request_purpose = value('Ціль запиту', 'request_purpose');
  if (!allowedPurpose.has(request_purpose)) { results.push(reject('UNSUPPORTED_PURPOSE', 'Непідтримувана ціль запиту')); continue; }
  const property_type = value('Тип нерухомості', 'property_type');
  if (!allowedType.has(property_type)) { results.push(reject('UNSUPPORTED_PROPERTY_TYPE', 'Непідтримуваний тип нерухомості')); continue; }
  const property_location = value("Місцезнаходження об'єкта", 'property_location');
  if (!property_location) { results.push(reject('MISSING_LOCATION', 'Не вказано місцезнаходження')); continue; }
  const rawDate = value('Бажана дата консультації', 'consultation_date');
  let consultation_date;
  let m = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) consultation_date = rawDate;
  else { m = rawDate.match(/^(\d{2})[./](\d{2})[./](\d{4})$/); if (m) consultation_date = `${m[3]}-${m[2]}-${m[1]}`; }
  const parsed = consultation_date ? new Date(`${consultation_date}T00:00:00Z`) : null;
  if (!parsed || Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0,10) !== consultation_date) { results.push(reject('INVALID_CONSULTATION_DATE', 'Некоректна дата консультації')); continue; }
  const source_row_id = String(data.source_row_id ?? `${stableId}:${encodeURIComponent(phone)}:${encodeURIComponent(full_name)}`);
  const additional_comments = String(data['Додаткові коментарі'] ?? data.additional_comments ?? '').trim() || null;
  results.push({ json: { validation_status: 'VALID', full_name, phone, request_purpose, property_type, property_location, consultation_date, additional_comments, source_row_id, processed_at: new Date().toISOString() } });
}
return results;

